def memoized_is_prime(n):
    if n < 2:
        return False
    cache = {}
    if n in cache:
        return cache[n]
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            cache[n] = False
            return False
    cache[n] = True
    return True

